INSERT INTO phpbb_privmsgs_text VALUES (2782, '1df632ae4e', 'just an FYI,\r\nit\'s not advisable to use spaces in file names either, it makes it harder for you later on.\r\n\r\nuse "_" underscores or capiTols for a naming convention.\r\nexamples would be:\r\n\r\nmy_image_file.jpg\r\nor\r\nmyImageFile.jpg\r\n\r\nif you do use spaces (which you shouldn\'t), you\'ll need to use: \r\n%20\r\nin the URL.\r\n%20 = " "\r\na space.');
