INSERT INTO phpbb_privmsgs_text VALUES (13853, '15938f3470', 'Well Dave not sure what teh cost and time this mod would take but I found this while loking around ebay.\r\n\r\n  Considering the Stock Xmod is 50 bones not sure it would be worth it but looks ok if the mod is cheap and easy.\r\n\r\n[url]http://cgi.ebay.com/ws/eBayISAPI.dll?ViewItem&amp;item=3157975108&amp;category=2565[/url]');
