INSERT INTO phpbb_privmsgs_text VALUES (14880, 'ba541e108f', '[quote:ba541e108f="fook yu"]Thanks man, didn\'t mean to make ya think I was a phony. Yes, I am bdebde, I had some trouble with my ISP and could no longer get email notifications from bitpimps, so I created the new account until regular mail is resolved (if ever).[/quote:ba541e108f]\r\n\r\ncool, that\'s good to know.\r\n\r\ncheers dude.\r\n\r\nmatt.');
