INSERT INTO phpbb_privmsgs_text VALUES (15969, 'd2acaab3ab', 'What\'s up Matt..... Long time no race...lol  How\'s it going ?\r\n\r\nThis weather is killing me over here.   Still interested in coming by, and racing a bit?\r\n\r\nThat\'d be really cool man. I still have that Beetle body for you.    You can call me, or PM me and let me know.. 727-906-3343\r\n\r\nI think I\'m off till Fri.\r\n\r\n\r\n\r\n-Steve');
