INSERT INTO phpbb_privmsgs_text VALUES (15572, '6845e953de', 'Wow, its been some time since I visited this site.\r\nI am ove on the west side of town, in the HEB area, between FtWorth and Irving.\r\nBeen a while since I played with my bits too, but I still buy a homie now and then');
