INSERT INTO phpbb_privmsgs_text VALUES (15720, '643155c2c4', 'Hey DT , I didn\'t forget about you . I just got back in from Missouri .\r\nMy ears are still poppin . I get it out to you next week .\r\n\r\n\r\n\r\ndenden');
