INSERT INTO phpbb_privmsgs_text VALUES (19053, '79b58e8387', 'Yo Dave,\r\n\r\nI got you three Precious Micro\'s for Da Auction.\r\n\r\nI\'ll get\'em in the mail this week along with 3 chassis for FET\'s.  Lemme know if you need anything else (motor, wheels, body, decals, etc.)\r\nPop me your email, I think you sent me your address again, the brain is fried from doin 6th grade math homework with Lil Matrix so I\'ll have to check for your address.  Ahh send it anyways, I\'m hittin da sack   :neutral:');
