INSERT INTO phpbb_privmsgs_text VALUES (16211, 'd619b05c94', 'hey,\r\nyou\'re right on the seed :smoking:\r\n\r\nand if you haven\'t gotten that e-mail yet.....you may want to check you\'re "bulk" or "junk" mail folder....its probably there......and save the address it came from in your contacts so I can send more pics in the future.....   8-)');
INSERT INTO phpbb_privmsgs_text VALUES (16212, 'ac494d88f6', '[quote:ac494d88f6="Havok"]hey,\r\nyou\'re right on the seed :smoking:\r\n\r\nand if you haven\'t gotten that e-mail yet.....you may want to check you\'re "bulk" or "junk" mail folder....its probably there......and save the address it came from in your contacts so I can send more pics in the future.....   8-)[/quote:ac494d88f6]Yeah I checked my bulk mail. You know, yahoo is kinda spotty sometimes. Just send it to my wife\'s email, strollerpusher@cox.net\r\n\r\nIt should go through there with no probs.\r\n\r\ndave');
