INSERT INTO phpbb_privmsgs_text VALUES (16482, '47899e0a49', '[quote:47899e0a49="SuperEMAXX"]How much would it cost me for you to make me some headlights?[/quote:47899e0a49]\r\n\r\nyou want the kit or have it done for you?\r\nblue or white leds?\r\nhow do you want them powered? seperate battery or off the car? runtime is less if the lights get their power off the car...\r\nI make a little pcb that converts the voltage from the car to 5V to drive the LED\'s. blue and white leds need the higher voltage\r\n\r\nph2t.');
