INSERT INTO phpbb_privmsgs_text VALUES (17770, '3a791e715e', '[quote:3a791e715e="Son_Gokou"] \r\n\r\nBut, I never knew someone ENJOYED my rants.... :eek:[/quote:3a791e715e]\r\n\r\nYeah... that\'s some pretty entertaining teen angst you got there....');
