INSERT INTO phpbb_privmsgs_text VALUES (19584, '4959b7fcb3', 'Holy shit! The Dirtbombs!! Man, that is some fuuuunnn shit. They remind me of Wilson Pickett in the gutter on speed. When the Stevie Wonder song played, I was beltin\' it out while doin\' some dishes... that\'s one of my favorite tunes of his (Livin\' for the City).\r\n\r\nThanks, man.. I should be mailin\' some stuff tomorrow or Saturday.');
