INSERT INTO phpbb_privmsgs_text VALUES (19759, '2201defb7a', 'fuck! lots to list!\r\n\r\niwaver: rx pcb, servo\r\n\r\nkyosho: clear chassis set, tierod, motor housing, screwset, xspeed motor, cf h plate, front springset(yellow), cf/alloy stabilizer bar, 20 degree tyres\r\n\r\nwfc: bearings, knuckles, wheelnuts\r\n\r\nxtra speed: 9t pinion, diff gear\r\n\r\nmegatech: triple alloy rear shockset\r\n\r\ntopcad: alloy bulkhead, motor clip\r\n\r\nyeah racing: crystals, wide alloy wheelset\r\n\r\nsecond hand ball diff, whoah nelly 1.0\r\n\r\n i think that\'s it. probably cost about $200us to get to this point.');
INSERT INTO phpbb_privmsgs_text VALUES (19760, '2201defb7a', 'fuck! lots to list!\r\n\r\niwaver: rx pcb, servo\r\n\r\nkyosho: clear chassis set, tierod, motor housing, screwset, xspeed motor, cf h plate, front springset(yellow), cf/alloy stabilizer bar, 20 degree tyres\r\n\r\nwfc: bearings, knuckles, wheelnuts\r\n\r\nxtra speed: 9t pinion, diff gear\r\n\r\nmegatech: triple alloy rear shockset\r\n\r\ntopcad: alloy bulkhead, motor clip\r\n\r\nyeah racing: crystals, wide alloy wheelset\r\n\r\nsecond hand ball diff, whoah nelly 1.0\r\n\r\n i think that\'s it. probably cost about $200us to get to this point.');
INSERT INTO phpbb_privmsgs_text VALUES (19761, 'e0ad97f552', '[quote:e0ad97f552="betty.k"]fuck! lots to list!\r\n\r\niwaver: rx pcb, servo\r\n\r\nkyosho: clear chassis set, tierod, motor housing, screwset, xspeed motor, cf h plate, front springset(yellow), cf/alloy stabilizer bar, 20 degree tyres\r\n\r\nwfc: bearings, knuckles, wheelnuts\r\n\r\nxtra speed: 9t pinion, diff gear\r\n\r\nmegatech: triple alloy rear shockset\r\n\r\ntopcad: alloy bulkhead, motor clip\r\n\r\nyeah racing: crystals, wide alloy wheelset\r\n\r\nsecond hand ball diff, whoah nelly 1.0\r\n\r\n i think that\'s it. probably cost about $200us to get to this point.[/quote:e0ad97f552]\r\n\r\n :eek: Wow, cool.\r\n\r\nJust wanted to know....wait a minute, don\'t you have ph2t\'s woah nelly?\r\n\r\nJust thought I could add a few suggestions...but hell, it\'s YOUR z, I\'m just mentioning a few things you could do to it:\r\n\r\nSince you have ph2t\'s woah nelly, try the Tamiya Plasma Dash motor armautre in a Ball Bearing motor can, or the 35T motor from www.minizworkshop.com\r\n\r\nAlso, for even more speed, you could get the....uhh, whatchamacallit.... Micro RS4 12T pinion...it\'s brass, so it may be a bit hard to get on.\r\n\r\nJust a few tips, hell even I\'m still learning about all the parts for a mini-z and what they\'re called!  :shock: \r\n\r\nOh, and thanks.');
INSERT INTO phpbb_privmsgs_text VALUES (19749, '02c4c2ec4b', 'Hey jowlz,\r\n\r\nHeres the lst if i never gave it to ya, ive revised it a bit.\r\n\r\n-Xmods AWD Kit ($10)\r\n\r\n-Xmods Shock/ Tie rod kit ($7.99)\r\n\r\n-Xmods Tyre set ($7.99)\r\n\r\n-Xmods Bearing Set ($19.99)\r\n\r\n-Xmods Light set ($5.99)\r\n\r\n-And I am really looking for the  3.82:1 (blue) and 4.40:1 (yellow) gearsets and pinions anyway ya can hook me up??\r\n\r\nAlso that wheelset you were talking about, what do ya want for it??\r\n\r\ncheers man\r\n\r\nJamie');
